  "p.issue_settings.roles_intro":
    "এই প্রতিষ্ঠান যে ভূমিকাগুলো স্বীকার করে, এবং ভূমিকা-সদস্যসহ একটি পরিকল্পনায় প্রতিটি কী অনুমোদন করে। একটি ভূমিকা শুধু কারও সাইন-ইন ইতিমধ্যে যা অনুমোদন করে তা সংকুচিত করতে পারে। একটি কর্মপ্রবাহ শুধু তালিকাভুক্ত ভূমিকার নাম দিতে পারে, যাতে ভুল বানানের ভূমিকায় কোনো স্থানান্তর সীমাবদ্ধ না হয়।",
