    "ইনবক্সের জন্য এবং প্রতিটি ধরনের গন্তব্যের জন্য প্রতিটি ধরনের বিজ্ঞপ্তি চালু বা বন্ধ করুন। ওয়েবহুক, চ্যাট বা ইমেলে অনুলিপি যায় শুধু তখনই, যখন আপনি নিচে সেই ধরনের গন্তব্য যোগ করেছেন। দৈনিক সারসংক্ষেপ একটি বিষয়ে একদিনের বিজ্ঞপ্তি ইনবক্সের একটি লাইনে জড়ো করে; কিছুই আটকে রাখা বা বাদ দেওয়া হয় না।",
