  "p.escalations.intro":
    "প্রকল্প নিজে যা মেটাতে পারে না বা মেটানো উচিত নয়, তা ওপরে জানান। এটি প্রকল্পের শাসন-ব্যবস্থা কাঠামোর উর্ধ্বতনকে জানানোর পথের একটি স্তরে উত্থাপিত হয়, স্বীকৃত হয়, কেউ উত্তর না দিলে এক স্তর ওপরে যায়, এবং সমাধান বা প্রত্যাহারে শেষ হয়। যাঁকে দায়িত্বপ্রাপ্ত হিসেবে নাম দেওয়া হয়েছে এবং যিনি এটি উত্থাপন করেছেন তাঁদের ইনবক্সে জানানো হয় (কোনো ইমেল পাঠানো হয় না)।",
