    "পরিচালক প্যাক হলো পরিচালকদের কাছে মাসের প্রতিবেদন, যা একবার খসড়া হয়, একজন নামকরা ব্যক্তি প্রকাশ করেন এবং তারপর স্থির হয়ে যায়: প্রকাশিত প্যাক কখনো বদলায় না, এবং সংশোধন হলো টীকাসহ একটি নতুন সংস্করণ। নিচের প্রতিটি সংখ্যা প্রকাশিত প্যাক থেকে পড়া; এখানে কিছুই পুনরায় হিসাব করা হয় না।",
