  "p.director_pack.basis":
    "রেকর্ডগুলো প্যাকের খসড়ার সময় যেমন ছিল তেমন, কাট-অফের দিন বা তার আগের তারিখের। সমস্যা ও পরিবর্তনের অনুরোধের কোনো অবস্থার ইতিহাস থাকে না, তাই কাট-অফের পরে কিন্তু খসড়ার আগে বন্ধ হওয়া একটি বন্ধ হিসেবে দেখায়। যে অংশে দেখানোর কিছু নেই তা সেটি জানায়; অনুপস্থিতি কখনো শূন্য বা সবুজ হিসেবে দেখানো হয় না।",
