    "একটি অনুদান ও একটি সংরক্ষিত তহবিল, যেসব বাজেট লাইন তা থেকে ব্যয় করে সেগুলো পর্যন্ত অনুসরণ করা। কোনো লাইনে এখনো পরিকল্পিত নয় এমন অর্থ অনুসরণহীন হিসেবে দেখানো হয়।",
  "p.demo.f_costs_t": "একটি প্রকল্পের ব্যয়",
  "p.demo.f_costs_d": "হারের সারণি থেকে শ্রম ব্যয় এবং কাজ অনুযায়ী অন্য ব্যয়।",
  "p.demo.f_resources_t": "সম্পদ",
  "p.demo.f_resources_d":
    "আটজন কাল্পনিক ব্যক্তি, তাঁদের ভূমিকা এবং তাঁরা কীসে বুক করা।",
  "p.demo.f_capacity_t": "সক্ষমতার হিটম্যাপ",
  "p.demo.f_capacity_d":
    "দক্ষতার পুল ও মাস অনুযায়ী সরবরাহ ও চাহিদা। লাল মাসগুলো দেখায় কোথায় সংকেত প্রকৌশলীর ঘাটতি।",
  "p.demo.f_key_persons_t": "মূল ব্যক্তি",
  "p.demo.f_key_persons_d":
    "একক ব্যর্থতা-বিন্দু: একজন প্রকৌশলী যাঁকে এখনো কেউ প্রতিস্থাপন করতে পারে না, এবং প্রস্তুত উত্তরসূরিসহ একটি ভূমিকা।",
  "p.demo.f_objectives_t": "উদ্দেশ্য",
  "p.demo.f_objectives_d":
    "তিনটি উদ্দেশ্য, প্রতিটি যে পরিকল্পনাগুলো তাকে সেবা দেয় সেগুলোর সঙ্গে যুক্ত।",
  "p.demo.f_okrs_t": "লক্ষ্য ও মূল ফলাফল",
  "p.demo.f_okrs_d": "চেক-ইন ও আস্থাসহ মূল ফলাফল।",
  "p.demo.f_kpis_t": "মূল পরিমাপ",
  "p.demo.f_kpis_d":
    "বিলম্বের মিনিট, যাত্রী সন্তুষ্টি এবং পরিকল্পনার বিপরীতে ব্যয়, প্রতি মাসে একটি পাঠসহ।",
  "p.demo.f_proposals_t": "কাজ গ্রহণ",
  "p.demo.f_proposals_d":
    "বিভিন্ন ধাপের পাঁচটি প্রস্তাব, খসড়া থেকে অনুমোদিত ও প্রত্যাখ্যাত পর্যন্ত।",
  "p.demo.f_ideas_t": "ধারণা",
  "p.demo.f_ideas_d": "ভোটসহ চারটি ধারণা। একটিকে প্রস্তাবে রূপান্তর করুন।",
  "p.demo.f_scenarios_t": "পরিস্থিতি",
  "p.demo.f_scenarios_d": "সংকেতের কাজ আগে হলে বাজেট সীমার মধ্যে কী খাপ খায়।",
  "p.demo.f_director_packs_t": "পরিচালক প্যাক",
  "p.demo.f_director_packs_d":
    "সেপ্টেম্বরের নির্বাহী ও বোর্ড প্যাক, সক্রিয় তথ্য থেকে সংকলিত। প্রতিটি অংশ দেখতে একটি খুলুন।",
  "p.demo.f_organizations_t": "অংশীদার প্রতিষ্ঠান",
  "p.demo.f_organizations_d":
    "কর্তৃপক্ষ, তার সরবরাহকারী সংস্থা, একজন অংশীদার ও একজন যোগানদার।",
  "p.demo.f_milestone_signoffs_t": "মাইলফলকের অনুমোদন",
  "p.demo.f_milestone_signoffs_d":
    "চালু হওয়ার জন্য অংশীদার ও যোগানদারকে স্বাক্ষর করতে হয়। যোগানদার করেছেন; অংশীদার করেননি, তাই চালু হওয়া সরবরাহিত কিন্তু পূরণ হয়নি।",
  "p.demo.f_cutover_t": "কাটওভার যাও/যেয়ো না",
  "p.demo.f_cutover_d":
    "তিনটি থামার মাপকাঠি, একটি পূরণ, একটি সহ-স্বাক্ষর জমা। “যাও” প্রত্যাখ্যাত হতো, এবং পর্দা কারণ জানায়।",
  "p.demo.f_deployment_moves_t": "স্থাপনা সরানো",
  "p.demo.f_deployment_moves_d":
    "স্থাপনার শুরু দুই সপ্তাহ সরানোর একটি অনুরোধ, অন্য কাজের ওপর তার ফলাফল ও শ্রম ব্যয়সহ, অনুমোদনের অপেক্ষায়।",
  "p.demo.f_start_queue_t": "শুরুর সারি",
  "p.demo.f_start_queue_d":
    "দুটি কর্মসূচি সরবরাহে আছে এবং সীমা দুই, তাই তৃতীয়টি ক্রমানুসারে সারিতে অপেক্ষা করে।",
  "p.demo.f_critical_chain_t": "ক্রান্তিক শৃঙ্খল",
  "p.demo.f_critical_chain_d":
    "নির্ভরশীল কাজ ও তাদের ভাগ করা ব্যক্তিদের মধ্য দিয়ে শৃঙ্খল, আগ্রাসী ও নিরাপদ প্রাক্কলনসহ।",
  "p.demo.f_buffers_t": "বাফার ব্যবস্থাপনা",
  "p.demo.f_buffers_d":
    "স্থির বাফার পরিকল্পনা, জ্বর চার্ট এবং একটি পুনরুদ্ধার পদক্ষেপ।",
  "p.demo.f_pipeline_t": "ড্রাম ও পাইপলাইন",
  "p.demo.f_pipeline_d":
    "যে দক্ষতার পুলের ওপর পোর্টফোলিও সবচেয়ে বেশি নির্ভর করে এবং প্রস্তাবিত পর্যায়ক্রমিক শুরু।",
  "p.demo.f_search_t": "অনুসন্ধান",
  "p.demo.f_search_d":
    "হেডারে ম্যাগনিফাইং গ্লাসে টাইপ করুন। এই লিঙ্ক “signal” অনুসন্ধান করে।",
  "p.demo.f_email_deliveries_t": "ইমেল সরবরাহ",
  "p.demo.f_email_deliveries_d":
    "সেবা যত ইমেল পাঠানোর চেষ্টা করেছে। ডেমো থেকে কিছু পাঠানো হয় না, তাই এই তালিকা ফাঁকা।",
  "p.demo.f_display_t": "প্রদর্শন সেটিংস",
  "p.demo.f_display_d": "লেখার আকার, থিম, সরল দৃশ্য ও ভাষা।",
