  "p.cutover.link": "কাটওভার যাও/যেয়ো না",
  "p.cutover.title": "কাটওভার যাও/যেয়ো না — PPM",
  "p.cutover.h1": "কাটওভার যাও/যেয়ো না",
  "p.cutover.lede":
    "একটি নিরাপত্তা-সংকটজনক ব্যবস্থায় কাটওভারের সিদ্ধান্ত। থামার মাপকাঠিগুলো আগে লিখে প্রকাশ করা হয়, এবং তারপর স্থির হয়ে যায়: বদলালে নতুন সংস্করণ হয়। “যাও”-এর জন্য প্রতিটি মাপকাঠি পূরণ এবং প্রতিটি প্রয়োজনীয় সহ-স্বাক্ষর লাগে। “যেয়ো না” বা নিরাপত্তার জন্য বিলম্ব হলো মাপকাঠির ভিত্তিতে নেওয়া সিদ্ধান্ত; এটি বিলম্ব নয়।",
