  "p.ledger.reconcile": "মেলান",
  "p.ledger.reconciled":
    "মেলানো হয়েছে: প্রতিটি সারি তার মুদ্রায় একটি লাইনের সঙ্গে কোনো পার্থক্য ছাড়াই মিলেছে।",
  "p.ledger.record_heading": "একটি বরাদ্দ লিপিবদ্ধ করুন",
  "p.ledger.record_says":
    "একটি অর্থায়নের উৎস যে অর্থ বরাদ্দ করেছে। বরাদ্দ যেমন লিপিবদ্ধ হয় তেমনই রাখা হয় এবং কখনো বদলানো হয় না।",
  "p.ledger.record": "বরাদ্দ লিপিবদ্ধ করুন",
  "p.ledger.recorded": "বরাদ্দ লিপিবদ্ধ হয়েছে।",
  "p.ledger.refused_export":
    "রপ্তানি পড়া যায়নি: প্রতিটি সারিতে একটি ব্যয় কোড, ক্ষুদ্র এককে একটি পূর্ণ পরিমাণ ও একটি মুদ্রা দরকার, সেবা যত নেয় তার বেশি নয়।",
  "p.ledger.refused_line":
    "লাইনটি সেই বরাদ্দ থেকে ব্যয় করতে পারে না: তাদের অর্থায়নের উৎস ও মুদ্রা একই হতে হবে।",
