  "p.signoffs.lede":
    "কিছু মাইলফলক পূরণ হয় শুধু তখনই যখন তাতে নাম দেওয়া অংশীদার প্রতিষ্ঠানগুলো তা অনুমোদন করে। সরবরাহিত হলো সরবরাহকারী প্রতিষ্ঠানের বলা যে কাজ শেষ; পূরণ হলো প্রতিটি অনুমোদন কার্যকর সহ সরবরাহিত। প্রত্যাহার করা অনুমোদন আবার বাকি হিসেবে গণ্য হয়।",
