  "p.organizations.lede":
    "যেসব প্রতিষ্ঠান পোর্টফোলিওতে সরবরাহ করে, পৃষ্ঠপোষকতা করে, যোগান দেয় বা অংশীদার। একটি প্যাক কোনো প্রতিষ্ঠানকে সম্বোধন করা যায়, একটি মাইলফলকে এর অনুমোদন লাগতে পারে, এবং এটি সক্ষমতা প্রতিশ্রুত করতে পারে। প্রতিষ্ঠান অবসরে পাঠালে এর ইতিহাস থাকে।",
