    "কোনো পোর্টফোলিও পরিকল্পিত ব্যয়ের বা উন্মুক্ত ঝুঁকির {concentration}% বা তার বেশি ধারণ করলে (অন্তত দুটি পোর্টফোলিও থাকলে), পরিকল্পিত ব্যয় বা ঝুঁকির অংশ লক্ষ্যমাত্রার মূল্যের অংশের চেয়ে {gap} শতাংশ পয়েন্ট বা তার বেশি হলে, অথবা নির্বাচিত মুদ্রায় পরিকল্পিত ব্যয় থাকলেও লক্ষ্যমাত্রার মূল্য না থাকলে একটি চিহ্ন দেওয়া হয়। চিহ্ন মানে দেখার তাগিদ, রায় নয়।",
