  "p.balance.notes":
    "পোর্টফোলিও অনুযায়ী ভাগ করা, বিভাগ বা কৌশলগত লক্ষ্য অনুযায়ী নয়: ব্যয়, সুবিধা-মূল্য ও ঝুঁকি, তিনটিই কেবল পোর্টফোলিও অনুযায়ী প্রতিবেদিত হয়। ব্যয় হলো বাজেট-সারির পরিকল্পিত অঙ্ক, মূল্য হলো লিপিবদ্ধ সুবিধাগুলোর লক্ষ্যমাত্রা, আর ঝুঁকি হলো উন্মুক্ত ঝুঁকির স্কোর; ভিন্ন মুদ্রার অর্থ কখনো যোগ করা হয় না।",
  "p.roadmap.title": "রোডম্যাপ — প্রভাব, প্রচেষ্টা এবং এখন / পরে / আরও পরে",
  "p.roadmap.h1": "রোডম্যাপ: প্রভাব, প্রচেষ্টা এবং এখন / পরে / আরও পরে",
  "p.roadmap.lede":
    "যেসব ধারণা ও প্রস্তাবের সিদ্ধান্ত এখনো বাকি, সেগুলো কতটা গুরুত্বপূর্ণ (প্রভাব) এবং কতটা কাজ লাগবে (প্রচেষ্টা) তার ভিত্তিতে সাজানো। সেবায় কোনো ধারণা বা প্রস্তাবের প্রভাব বা প্রচেষ্টা রাখা হয় না, তাই এখানে আপনি প্রতিটির মূল্যায়ন করেন; আপনার মূল্যায়ন শুধু এই ব্রাউজারে থাকে, সেবায় পাঠানো বা অন্যদের সঙ্গে ভাগ করা হয় না। দুটি মূল্যায়ন না থাকলে বিষয়টি বসানো হয় না।",
