    "এই প্রতিশ্রুতি কর্মীবাহিনী সেবায় পাঠানো হয় না: শুধু এর সঙ্গে যুক্ত পুলের চাহিদা পাঠানো হয়।",
  "p.commitments.out_none_yet":
    "এই কর্মসূচি, পুল ও মাসের জন্য কর্মীবাহিনী সেবায় এখনো কিছু পাঠানো হয়নি।",
  "p.commitments.out_started":
    "কর্মীবাহিনী সেবায় {fte} পূর্ণকালীন সমতুল্য (এই পুল ও মাসের জন্য কর্মসূচির মোট) পাঠানো হচ্ছে। এর উত্তর সাম্প্রতিক প্রেরণের অধীনে দেখা যাবে।",
  "p.commitments.out_started_zero":
    "মোট এখন শূন্য হওয়ায় কর্মীবাহিনী সেবা থেকে এই পুল ও মাসের জন্য কর্মসূচির সংখ্যা প্রত্যাহার করা হচ্ছে। এর উত্তর সাম্প্রতিক প্রেরণের অধীনে দেখা যাবে।",
  "p.commitments.out_sent": "কর্মীবাহিনী সেবা {fte} পূর্ণকালীন সমতুল্য গ্রহণ করেছে।",
  "p.commitments.out_sent_zero":
    "কর্মীবাহিনী সেবা এই কর্মসূচি, পুল ও মাসের সংখ্যা প্রত্যাহার করেছে।",
  "p.commitments.out_duplicate":
    "কর্মীবাহিনী সেবার কাছে এই সংখ্যা আগেই ছিল; সেখানে কিছু বদলায়নি।",
  "p.commitments.out_refused":
    "কর্মীবাহিনী সেবা এটি প্রত্যাখ্যান করেছে। কিছুই পুনরায় চেষ্টা করা হয় না; আবার পাঠাতে আবার সংরক্ষণ করুন।",
  "p.commitments.out_unreachable":
    "কর্মীবাহিনী সেবার সঙ্গে যোগাযোগ করা যায়নি, অথবা সময়মতো উত্তর আসেনি। কিছুই পুনরায় চেষ্টা করা হয় না; আবার পাঠাতে আবার সংরক্ষণ করুন।",
  "p.commitments.out_not_configured":
    "পাঠানো হয়নি: এই সেবা কর্মীবাহিনী সেবার সঙ্গে যোগাযোগের জন্য সাজানো নেই।",
  "p.commitments.out_no_token":
    "পাঠানো হয়নি: কর্মীবাহিনী সেবায় এগিয়ে দেওয়ার মতো কোনো সাইন-ইন ছিল না।",
  "p.commitments.out_too_large":
    "পাঠানো হয়নি: কর্মীবাহিনী সেবা সর্বোচ্চ ১০ ০০০ পূর্ণকালীন সমতুল্য নেয়।",
