    "প্রত্যাখ্যাত: এই উত্তরণ প্রত্যাহার হয়েছে, অথবা ইতিমধ্যে ভিন্ন ফলাফল বা উত্তরসহ নিষ্পত্তি হয়েছে; নিষ্পত্তি কখনো উপরে লেখা হয় না। এটি আবার পড়া হয়েছে।",
