  "p.escalations.records_rules":
    "স্বীকার করতে উত্তরণ স্বীকারের অধিকার এবং নিষ্পত্তি করতে নিষ্পত্তির অধিকার লাগে; প্রশাসকের দুটিই আছে, এবং এই পাতা আগে থেকে বলতে পারে না আপনার আছে কি না। স্বীকৃতি বর্তমান স্তরে গণ্য: এক স্তর ওপরে তুললে তা মুছে যায়। নিষ্পত্তি একটি লিপি এবং কখনো উপরে লেখা হয় না।",
