  "p.register_completeness.link": "নিবন্ধনের পূর্ণতা",
  "p.register_completeness.title": "নিবন্ধনের পূর্ণতা",
  "p.register_completeness.title_ppm": "নিবন্ধনের পূর্ণতা — PPM",
  "p.register_completeness.intro":
    "প্রতিটি কর্মসূচির নিবন্ধন কতটা সম্পূর্ণ: কর্মসূচির নথিতে যা থাকা উচিত তার কত অংশ আছে, এবং যা নেই তার প্রতিটির নাম। শুধু আপনি পড়তে পারেন এমন কর্মসূচি (Program ধরনের পরিকল্পনা) তালিকাভুক্ত।",
  "p.register_completeness.rules":
    "দশটি: একজন জ্যেষ্ঠ দায়িত্বশীল মালিক (কর্মসূচির নেতা একজনের স্থানে গণ্য), অংশীদার, একটি ধাপ, একটি সময়সূচির বেসলাইন, একটি লক্ষ্যমাত্রার তারিখ, একটি বাজেট, প্রতিটি বাজেট-সারিতে একটি অর্থের উৎস, একটি বাস্তবায়ন-আস্থার মূল্যায়ন, ঝুঁকি ও নির্ভরতা। অংশীদার চাওয়া হয় শুধু যেখানে বাস্তবায়ন-মডেলে অংশীদার আছে, এবং অর্থের উৎস শুধু যেখানে বাজেট-সারি আছে। কর্মসূচি ও তার অধীন পরিকল্পনা একসঙ্গে গণ্য।",
  "p.register_completeness.switch_on":
    "“নিবন্ধন নেই, অর্থ নেই” চালু: অসম্পূর্ণ কর্মসূচিতে বাজেট-সারি ছাড়া বা দৃঢ় বরাদ্দ বুক করা প্রত্যাখ্যাত হয়, কী নেই তা উল্লেখ করে।",
  "p.register_completeness.switch_off":
    "“নিবন্ধন নেই, অর্থ নেই” বন্ধ: অসম্পূর্ণ কর্মসূচিতে বাজেট-সারি ছাড়া বা দৃঢ় বরাদ্দ বুক করা এগিয়ে যায়, এবং সতর্কতা নিরীক্ষা-পথে রাখা হয়।",
  "p.register_completeness.count_one": "{n}টি কর্মসূচির মধ্যে {complete}টি সম্পূর্ণ।",
