  "p.meetings.intro":
    "সভা একটি শিরোনাম, একটি তারিখ ও একটি কার্যসূচিসহ পরিকল্পনা করা হয়। পরে এটি একবার অনুষ্ঠিত হিসেবে লিপিবদ্ধ হয়, কার্যবিবরণী ও ফলাফলসহ (সিদ্ধান্ত, কর্মপদক্ষেপ ও টীকা), অথবা বাতিল হয়। অনুষ্ঠিত বা বাতিল সভা একটি লিপি: অনুষ্ঠিত সভার কার্যবিবরণী সংশোধন করা যায় না এবং বাতিল সভা পুনরুদ্ধার করা যায় না। উপস্থিতদের লিপিবদ্ধ করা হয় না।",
