    "একটি ব্যক্তিগত ঠিকানা যাতে ক্যালেন্ডার অ্যাপ সাবস্ক্রাইব করতে পারে: নির্ধারিত তারিখসহ আপনার নামে নির্ধারিত উন্মুক্ত কাজ, তাদের পরিকল্পনার মাইলফলক ও স্প্রিন্ট, এবং আপনার পরিকল্পিত সময়। দ্বিতীয় ঠিকানাটি ফিড রিডারের জন্য আপনার বিজ্ঞপ্তির ফিড। যার কাছে ঠিকানা আছে সে তা যা দেখায় তা পড়তে পারে, তাই এটি নিজের কাছে রাখুন।",
  "p.feed.rules":
    "ঠিকানা এখানে একবারই দেখানো হয়, এবং এই পাতা তা রাখে না; এটি ৩৬৫ দিন চলে। নতুন একটি বানালে আগেরটি সঙ্গে সঙ্গে বন্ধ হয়।",
  "p.feed.issue": "একটি ফিড ঠিকানা বানান",
  "p.feed.confirm_issue":
    "নতুন ফিড ঠিকানা বানাবেন? আগে বানানো যেকোনো ঠিকানা সঙ্গে সঙ্গে কাজ করা বন্ধ করবে।",
  "p.feed.issued":
    "আপনার নতুন ঠিকানা নিচে। এখনই অনুলিপি করুন: এগুলো আর দেখানো হয় না।",
  "p.feed.calendar_address": "ক্যালেন্ডার ঠিকানা (iCalendar)",
  "p.feed.atom_address": "বিজ্ঞপ্তির ফিড ঠিকানা (Atom)",
  "p.feed.revoke": "প্রতিটি ফিড ঠিকানা বন্ধ করুন",
  "p.feed.confirm_revoke":
    "আপনার বানানো প্রতিটি ফিড ঠিকানা বন্ধ করবেন? কোনো একটি ব্যবহার করা ক্যালেন্ডার অ্যাপ সঙ্গে সঙ্গে হালনাগাদ হওয়া বন্ধ করবে।",
  "p.feed.revoked": "আপনার বানানো প্রতিটি ফিড ঠিকানা কাজ করা বন্ধ করেছে।",
  "p.feed.no_address":
    "উত্তরে এই পাতা দেখাতে পারে এমন কোনো ঠিকানা ছিল না, তাই কিছু দেখানো হয়নি। আগের যেকোনো ঠিকানা বন্ধ হয়েছে; দরকার হলে আরেকটি বানান।",
  "p.feed.refused_forbidden": "আপনি ফিড ঠিকানা পরিচালনা করতে পারেন না।",
  "p.feed.could_not_issue": "ফিড ঠিকানা বানানো যায়নি।",
  "p.feed.could_not_revoke": "ফিড ঠিকানা বন্ধ করা যায়নি।",
  "p.watching.heading": "আপনি যা অনুসরণ করেন",
  "p.watching.says":
    "আপনি যা অনুসরণ করেন তা বদলালে আপনাকে জানানো হয়। আপনি কোনো কাজ তৈরি করলে, তাতে মন্তব্য করলে বা তা আপনাকে দেওয়া হলে সেটি অনুসরণ করেন, যদি না বিজ্ঞপ্তির পছন্দে তা বন্ধ করে থাকেন। কে অনুসরণ করেন তা আর কাউকে জানানো হয় না। পরিকল্পনার নাম দেওয়া হয়; বাকি সবকিছু তার ধরন ও রেফারেন্সের শুরু দিয়ে দেখানো হয়।",
