  "p.workprofile.heading": "সময় ধরে কাজ",
  "p.workprofile.says":
    "আপনার পড়তে পারা প্রতিটি পরিকল্পনার কাজগুলোর বহন করা কাজ, প্রতিটি কাজের কর্মদিবসে তার রেখা অনুযায়ী ছড়ানো, পূর্ণ মিনিটে। যে কাজ বসানো যায় না (এখনো সময়সূচিভুক্ত নয় এমন কাজ, বা কর্মদিবসহীন কাজ) তা আলাদা গোনা হয়, কখনো বাদ দেওয়া হয় না।",
