  "p.hammock.heading": "হ্যামক: অন্যদের জুড়ে থাকা সারসংক্ষেপ কাজ",
  "p.hammock.says":
    "হ্যামক হলো এমন একটি সারসংক্ষেপ যার তারিখ এই পরিকল্পনার যেসব কাজের সঙ্গে এটি যুক্ত তাদের থেকে আসে, সবচেয়ে আগের শুরু থেকে সবচেয়ে পরের শেষ পর্যন্ত। এটি নির্ভরতা-নেটওয়ার্কে নেই, তাই কোনো কাজের ফ্লোট বা শেষ কখনো বদলায় না। একটি কাজ হ্যামক হয় শুধু যখন তার কোনো মেয়াদ, কাজ, সীমাবদ্ধতা বা নির্ভরতা নেই, এবং এর পরিকল্পিত শুরু মুছে ফেলা হয়; আবার কাজ বানালে এর প্রতিটি সংযোগ সরে যায়। হ্যামক এই পরিকল্পনার একটি কাজ বা অন্য হ্যামকের সঙ্গে যুক্ত হয়, নিজের সঙ্গে নয়, দুবার নয় এবং চক্রে নয়।",
  "p.hammock.none": "এই পরিকল্পনায় কোনো হ্যামক নেই।",
