    "এগুলো আপনার পড়তে পারা অন্য পরিকল্পনার কাজ, যার সঙ্গে এই পরিকল্পনার কাজগুলো যুক্ত, নিজ নিজ পরিকল্পনার ক্যালেন্ডারে সময়সূচিভুক্ত। ড্যাশযুক্ত দণ্ড হলো ক্রিটিক্যাল পাথের বাইরের কাজ; নিরেট দণ্ড ও হীরা চিহ্ন তার ভেতরের কাজ বোঝায়।",
