  "p.crossplan.task_says":
    "নির্ভরতা এই কাজকে আপনার পড়তে পারা অন্য পরিকল্পনার একটি কাজের সঙ্গে যুক্ত করে। না বাছলে এর ধরন শেষ থেকে শুরু; এর বিলম্ব ঋণাত্মক {max} থেকে {max} পর্যন্ত পূর্ণ কার্যদিবস, ঋণাত্মক বিলম্ব হলো অগ্রগামিতা। একই উপায়ে, পরিকল্পনা জুড়ে চক্রে, বা হ্যামকের সঙ্গে নির্ভরতা দুবার তৈরি হয় না। যার অন্য প্রান্ত আপনি পড়তে পারেন না তা গোনা হয়, কখনো নাম দেওয়া হয় না, এবং সময়সূচি থেকে বাদ যায়।",
