  "p.workingtime.says":
    "একটি কর্মদিবস কতক্ষণের (১ মিনিট থেকে ২৪ ঘণ্টা) এবং সপ্তাহে কত দিন কাজ হয় (১ থেকে ৭), এই পরিকল্পনার জন্য বা প্রতিষ্ঠানের ডিফল্ট হিসেবে। প্রতিটি একটি নতুন লিপি যা এখানে বদলানো বা সরানো যায় না, তাই আগে আপনাকে জিজ্ঞাসা করা হয়; এই পরিকল্পনার জন্য দ্বিতীয়টি প্রত্যাখ্যাত হয়।",
