  "p.workingtime.away_says":
    "ছুটি, অবকাশ, অধ্যয়ন-ছুটি বা প্রকল্পের বাইরের দায়িত্ব, একজন ব্যক্তির জন্য প্রথম থেকে শেষ দিন পর্যন্ত, যাতে সেই সময় অলস হিসেবে পড়া না হয়। ব্যক্তি person: এবং একটি আইডির মতো রেফারেন্স। একবার লিপিবদ্ধ হলে এটি বদলানো বা সরানো যায় না, তাই আগে আপনাকে জিজ্ঞাসা করা হয়; ফাঁকা টীকা পাঠানো হয় না।",
