    "যেসব সারি এখানে আগে থেকে থাকা কোনো পরিকল্পনার মতো দেখায়, সেগুলো রাখা হয়, তৈরি হয় না। প্রতিটির সিদ্ধান্ত নিন: নতুন পরিকল্পনা হিসেবে তৈরি করুন, বা সদৃশ হিসেবে বাদ দিন। যে পরিকল্পনার মতো দেখায় তার সঙ্গে একীভূত করার সুযোগ এখানে নেই: বাদ দিন, তারপর পরিকল্পনার তালিকা থেকে পরিকল্পনাগুলো একীভূত করুন।",
